# =========================================================== chapter 6: sentence skills
ch = p.chapter("sentence-skills", "Sentences: types, voice, reported speech and conditionals", REF)
fig_types = grid([("statement", "I like fufu."), ("question", "Do you like it?"), ("command", "Eat your food."), ("exclamation", "How tasty it is!")], 2, 150, 62)
build(ch, "sentence-types", "Types of sentences: statements, questions, commands, exclamations; simple and compound", 30,
    ["Name the four kinds of sentence by their purpose.", "Tell a simple sentence from a compound and a complex sentence.", "Join short sentences with and, but, so, because."],
    [("key", "definition", "Four kinds of sentence", "A **statement** tells us something and ends with a full stop: *I like fufu.* A **question** asks something and ends with a question mark: *Do you like it?* A **command** tells someone to do something: *Eat your food.* An **exclamation** shows strong feeling and ends with an exclamation mark: *How tasty it is!*"),
     ("fig", fig_types, "Four kinds of sentence.", "Four boxes: statement (I like fufu), question (Do you like it), command (Eat your food) and exclamation (How tasty it is)."),
     ("key", "definition", "Simple, compound and complex", "A **simple** sentence has one main idea: *It rained.* A **compound** sentence joins two main ideas with **and, but, or, so**: *It rained, so we stayed inside.* A **complex** sentence has a main idea and an extra idea that cannot stand alone, joined with words like **because, when, if, although**: *We stayed inside because it rained.*"),
     ("key", "pieges", "Common mistakes", "- Writing two sentences with only a comma between them (*It rained, we stayed in*): use a full stop, or add a joining word.\n- Starting a sentence with *Because...* and not finishing it (*Because it rained.*). It needs a main idea: *Because it rained, we stayed in.*\n- Using both *although* and *but* in one sentence."),
     ("ex", "Example 1", "Say which kind of sentence each is: (a) Close the door. (b) What a beautiful day!", ["(a) It tells someone to do something and has no exclamation: it is a command.", "(b) It shows strong feeling and ends with an exclamation mark: it is an exclamation."], "(a) command; (b) exclamation."),
     ("ex", "Example 2", "Join the two sentences with a joining word: It was raining. We stayed inside.", ["The second idea is a result of the first, so we can use so: It was raining, so we stayed inside.", "Or we can use because to make a complex sentence: We stayed inside because it was raining."], "It was raining, so we stayed inside.")],
    [M("application", "What kind of sentence is: Where do you live?", "question", ["statement", "command", "exclamation"], "It asks something and ends with ?"),
     M("application", "Which sentence is a command?", "Please sit down.", ["He sat down.", "Why did he sit?", "How tired he is!"], "A command tells someone to do something."),
     M("application", "Which word joins the ideas in: I was tired, but I finished my work.?", "but", ["I", "was", "finished"], "But joins two main ideas that are different."),
     MA("approfondissement", "Match each sentence to its kind.", [("Is it Monday today?", "question"), ("Wash your hands.", "command"), ("Today is Monday.", "statement"), ("What a surprise!", "exclamation")], "Look at the purpose and the end mark."),
     TF("approfondissement", "'We stayed inside because it rained' is a compound sentence.", False, "Because makes it a complex sentence. A compound sentence uses and, but, or, so."),
     P("Read: Ada was hungry, so she bought a puff-puff. She ate it quickly because she was late for school. What a delicious snack!",
       [PM("What kind of sentence is the last sentence?", "exclamation", ["question", "command", "statement"], "It shows strong feeling and ends with !"),
        PM("Which word makes the first sentence compound?", "so", ["Ada", "hungry", "bought"], "So joins two main ideas."),
        PM("Which word makes the second sentence complex?", "because", ["quickly", "ate", "school"], "Because introduces the reason (an idea that cannot stand alone)."),
        PM("Which sentence would be a command?", "Buy a puff-puff.", ["She bought a puff-puff.", "Did she buy a puff-puff?", "What a puff-puff!"], "A command tells someone to do something.", points=2)])],
    [("Which ends with an exclamation mark?", "How cold it is!", ["Is it cold?", "It is cold.", "Put on a coat."], "An exclamation shows strong feeling."),
     ("'Open your books.' is a...", "command", ["question", "statement", "exclamation"], "It tells people what to do."),
     ("Which word makes a compound sentence?", "and", ["because", "if", "when"], "And joins two main ideas of equal importance."),
     ("Which is a question?", "Are you ready?", ["You are ready.", "Be ready.", "How ready you are!"], "It asks and ends with ?"),
     ("'Although it was late, we kept working.' is a...", "complex sentence", ["simple sentence", "compound sentence", "command"], "Although begins a side idea.")],
    ["Simple/compound/complex are introduced at an elementary level; check how far the Class 6 syllabus goes."],
    prereq=["fslc-english-parts-of-speech"])

# ---- active and passive
fig_ap = shapes([RECT(20, 25, 360, 80, fill="lightblue", radius=6), T(200, 48, "Active", 14, bold=True),
                 T(200, 78, "Ada ate the mango.", 18),
                 LINE(200, 108, 200, 130, arrow="end"),
                 RECT(20, 135, 360, 80, fill="lightyellow", radius=6), T(200, 158, "Passive", 14, bold=True),
                 T(200, 188, "The mango was eaten by Ada.", 18)], 400, 230)
build(ch, "active-passive", "Active and passive voice", 30,
    ["Tell an active sentence from a passive sentence.", "Change a simple active sentence into the passive and back.", "Use the passive correctly in the present, past and future."],
    [("key", "definition", "Active and passive", "In an **active** sentence the subject does the action: *Ada ate the mango.* In a **passive** sentence the action is done **to** the subject: *The mango was eaten by Ada.* We use the passive when the doer is not important or not known: *The window was broken.*"),
     ("fig", fig_ap, "The same idea in the active and in the passive.", "Two boxes joined by an arrow. The first says Active: Ada ate the mango. The second says Passive: The mango was eaten by Ada."),
     ("key", "methode", "How to make the passive", "1. Take the **object** of the active sentence: it becomes the new subject.\n2. Use the verb **be** in the same tense + the **past participle**: is/are eaten, was/were eaten, will be eaten.\n3. Add **by** + the doer (if needed).\nPresent: *Mama cooks rice.* → *Rice is cooked by Mama.* Past: *Mama cooked rice.* → *Rice was cooked by Mama.* Future: *Mama will cook rice.* → *Rice will be cooked by Mama.*"),
     ("key", "pieges", "Common mistakes", "- Forgetting the verb **be**: *The mango eaten by Ada* is wrong.\n- Using the wrong past participle: *was ate* (wrong), *was eaten* (right).\n- Not changing the be-verb to match the new subject: *The books was sold* (wrong), *The books were sold* (right).\n- Only verbs that take an object can become passive: we cannot say *The boy was slept*."),
     ("ex", "Example 1", "Change to the passive: The farmer planted maize.", ["The object (maize) becomes the subject.", "The verb is in the past: was + planted.", "Add by + the doer: by the farmer."], "Maize was planted by the farmer."),
     ("ex", "Example 2", "Change to the active: The window was broken by the boy.", ["The doer is the boy: he becomes the subject.", "The verb was broken becomes the simple past: broke.", "The window is the object."], "The boy broke the window.")],
    [M("application", "Which sentence is passive?", "The letter was written by Ngu.", ["Ngu wrote the letter.", "Ngu is writing a letter.", "Ngu will write a letter."], "The letter receives the action: was written."),
     M("application", "Change to the passive: Mama cooks rice.", "Rice is cooked by Mama.", ["Rice was cooked by Mama.", "Rice cooked by Mama.", "Mama is cooked by rice."], "Present simple: is + past participle."),
     M("application", "Change to the active: The ball was kicked by the boy.", "The boy kicked the ball.", ["The boy kicks the ball.", "The ball kicked the boy.", "The boy was kicking the ball."], "Same tense (past) and the doer first."),
     O("Change into the passive: The teacher will mark the books tomorrow.", "The books will be marked by the teacher tomorrow.", "Full marks: the books as subject, will be marked, by the teacher (accept without 'by the teacher'). Half marks for correct tense but wrong word order.", points=3),
     TF("approfondissement", "'The books was sold' is correct.", False, "Books is plural, so we need were: The books were sold."),
     P("Change these sentences. (a) The children sang the song. (b) A thief stole the bag. (c) The shop sells bread.",
       [PM("(a) in the passive:", "The song was sung by the children.", ["The song sang by the children.", "The song was sang by the children.", "The children were sung the song."], "Past: was + past participle sung."),
        PM("(b) in the passive:", "The bag was stolen by a thief.", ["The bag was stole by a thief.", "The bag stolen by a thief.", "A thief was stolen the bag."], "Past participle of steal is stolen."),
        PM("(c) in the passive:", "Bread is sold by the shop.", ["Bread was sold by the shop.", "Bread sells by the shop.", "The shop is sold bread."], "Present simple: is + sold.", points=2)])],
    [("The passive of 'Ada broke the cup' is...", "The cup was broken by Ada.", ["The cup is broken by Ada.", "The cup was break by Ada.", "Ada was broken by the cup."], "Past tense: was + broken."),
     ("Which verb form is used in the passive?", "be + past participle", ["have + base verb", "do + -ing", "can + base verb"], "For example: is cooked, was written."),
     ("Which sentence is active?", "The dog chased the cat.", ["The cat was chased by the dog.", "The cat is chased by the dog.", "The cat will be chased."], "The subject, the dog, does the action."),
     ("'Rice is grown in Cameroon.' The doer is...", "not mentioned", ["rice", "Cameroon", "grown"], "The passive can leave out the doer."),
     ("The passive of 'They will build a bridge' is...", "A bridge will be built.", ["A bridge will build.", "A bridge was built.", "A bridge is building."], "Future passive: will be + past participle.")],
    ["Only the simple present, simple past and simple future are used; check whether the syllabus includes other tenses (present continuous, perfect)."],
    prereq=["fslc-english-tenses-main"])

# ---- direct and indirect speech
fig_ds = grid([("now", "then"), ("today", "that day"), ("tomorrow", "the next day"), ("yesterday", "the day before"),
               ("here", "there"), ("this", "that"), ("I / my", "he, she / his, her"), ("will / can", "would / could")], 4, 92, 62, size=12)
build(ch, "direct-indirect", "Direct and indirect (reported) speech", 35,
    ["Tell direct speech from indirect speech.", "Change statements, questions and commands into indirect speech.", "Change tenses, pronouns and time words correctly."],
    [("key", "definition", "Direct and indirect speech", "**Direct speech** gives the exact words of a speaker, with quotation marks: *Mama said, “I am cooking rice.”* **Indirect (reported) speech** tells what was said, without quotation marks: *Mama said that she was cooking rice.* In reported speech the tense usually moves one step back: am → was, will → would, can → could, cooks → cooked."),
     ("fig", fig_ds, "Words that change in reported speech.", "Eight boxes of word pairs: now becomes then, today becomes that day, tomorrow becomes the next day, yesterday becomes the day before, here becomes there, this becomes that, I and my become he or she, will and can become would and could."),
     ("key", "methode", "Questions and commands", "- **Statement**: use *that* (or nothing): She said, “I am tired.” → She said (that) she was tired.\n- **Question**: use *asked* + **if / whether** (yes-no) or the question word (wh-). Normal word order, no question mark: He asked, “Where do you live?” → He asked where I lived.\n- **Command**: use *told / asked* + person + **to**: The teacher said, “Open your books.” → The teacher told us to open our books."),
     ("key", "pieges", "Common mistakes", "- Keeping the question word order: *He asked where did I live* is wrong; say *where I lived*.\n- Forgetting to change the pronoun (I → he or she) and the time word (tomorrow → the next day).\n- Keeping the quotation marks and the question mark in indirect speech."),
     ("ex", "Example 1", "Change to indirect speech: Ngu said, “I will come tomorrow.”", ["Say that. I becomes he, will becomes would.", "Tomorrow becomes the next day.", "Ngu said that he would come the next day."], "Ngu said that he would come the next day."),
     ("ex", "Example 2", "Change to indirect speech: Bih asked, “Where is my pen?”", ["Use asked and the question word where, with statement word order.", "My becomes her, is becomes was.", "Bih asked where her pen was."], "Bih asked where her pen was.")],
    [M("application", "Change to indirect speech: Mama said, “I am cooking rice.”", "Mama said that she was cooking rice.", ["Mama said that I am cooking rice.", "Mama said that she is cooked rice.", "Mama said, that she was cooking rice?"], "I becomes she; am cooking becomes was cooking."),
     M("application", "Which is the reported form of 'tomorrow'?", "the next day", ["yesterday", "that night", "the day before"], "Tomorrow becomes the next day."),
     M("application", "Change: The teacher said to us, “Open your books.”", "The teacher told us to open our books.", ["The teacher said to open your books.", "The teacher told us that open our books.", "The teacher asked us that we open books."], "A command uses told + person + to + verb."),
     O("Change to indirect speech: Ada asked, “Do you like mangoes?”", "Ada asked if (whether) I liked mangoes.", "Full marks: asked + if/whether, I liked (past tense, statement order), no question mark. Accept 'asked me if/whether I liked mangoes'.", points=3),
     TF("approfondissement", "In indirect speech we keep the quotation marks.", False, "Quotation marks are only for the exact words (direct speech)."),
     P("Change to indirect speech. (a) Che said, “I can swim.” (b) The nurse said to Mary, “Take this medicine today.” (c) Eko asked, “Why are you late?”",
       [PM("(a)", "Che said that he could swim.", ["Che said that he can swim.", "Che said he swimming.", "Che said, “he could swim.”"], "can becomes could; I becomes he."),
        PM("(b)", "The nurse told Mary to take that medicine that day.", ["The nurse told Mary take this medicine today.", "The nurse said Mary to take this medicine today.", "The nurse told Mary that take that medicine."], "A command: told + person + to; this → that, today → that day."),
        PM("(c)", "Eko asked why I was late.", ["Eko asked why was I late.", "Eko asked why you are late?", "Eko asked, why I was late?"], "Question word + normal word order, no question mark.", points=2)])],
    [("Reported speech: tense usually goes...", "one step back", ["one step forward", "to the future", "does not change"], "am → was, will → would."),
     ("He said, “I am happy.” → He said that he ......", "was happy", ["is happy", "am happy", "will be happy"], "Am becomes was and I becomes he."),
     ("Which sentence is in indirect speech?", "She said that she was ready.", ["She said, “I am ready.”", "“I am ready,” she said.", "She said: I am ready."], "No quotation marks, tense changed."),
     ("“Come here,” said the teacher. → The teacher told us ......", "to go there", ["come here", "that we come here", "going there"], "Command: to + verb; here becomes there."),
     ("The question mark disappears in...", "indirect questions", ["direct speech", "all sentences", "commands only"], "He asked where I lived. No question mark.")],
    ["Back-shifting rules are given in simplified form; special cases (reporting a general truth, past perfect) are not covered."],
    prereq=["fslc-english-active-passive", "fslc-english-punctuation"])

# ---- conditionals
fig_cond = shapes([RECT(20, 20, 360, 55, fill="lightblue", radius=6), T(200, 42, "Real: If + present, will + verb", 14, bold=True), T(200, 64, "If it rains, we will stay at home.", 13),
                   RECT(20, 85, 360, 55, fill="lightyellow", radius=6), T(200, 107, "Unreal: If + past, would + verb", 14, bold=True), T(200, 129, "If I had a bike, I would ride to school.", 13),
                   RECT(20, 150, 360, 55, fill="lightgreen", radius=6), T(200, 172, "Always true: If + present, present", 14, bold=True), T(200, 194, "If you heat ice, it melts.", 13)], 400, 220)
build(ch, "conditionals", "Conditional sentences", 30,
    ["Form real conditionals (if + present, will) and unreal conditionals (if + past, would).", "Use the right verb form after if.", "Complete and write conditional sentences."],
    [("key", "definition", "What is a conditional?", "A **conditional** sentence has an **if**-part (the condition) and a main part (the result). *If it rains, we will stay at home.* The if-part can come first (with a comma) or second (no comma): *We will stay at home if it rains.*"),
     ("fig", fig_cond, "Three kinds of conditional sentence.", "Three boxes. The first shows a real condition: if it rains, we will stay at home. The second shows an unreal one: if I had a bike, I would ride to school. The third shows a fact: if you heat ice, it melts."),
     ("key", "methode", "Which form?", "- **Real or possible** (it may happen): **if + present simple, will + verb**. *If you study, you will pass.*\n- **Unreal or unlikely** (it is not true now): **if + past simple, would + verb**. *If I were a bird, I would fly.* We often say *were* for all persons after if (*if I were*, *if he were*).\n- **Always true** (a fact): **if + present, present**. *If you mix red and blue, you get purple.*"),
     ("key", "pieges", "Common mistakes", "- Using will after if: *If it will rain* is wrong; say *If it rains*.\n- Mixing the forms: *If I had money, I will buy a bike* is wrong; say *I would buy*.\n- Forgetting the comma when the if-part comes first.\n- Using *would* in the if-part: *If I would know* is wrong; say *If I knew*."),
     ("ex", "Example 1", "Complete: If it rains tomorrow, we ...... (stay) at home.", ["Rain tomorrow is possible, so this is a real condition.", "The if-part is in the present (rains), so the result takes will + verb."], "we will stay at home."),
     ("ex", "Example 2", "Complete: If I ...... (be) a bird, I would fly over Mount Cameroon.", ["A person cannot be a bird, so this is unreal.", "The if-part is in the past, and we use were: if I were a bird."], "If I were a bird...")],
    [M("application", "Choose: If you ......, you will pass the exam.", "study", ["will study", "studied", "would study"], "Real condition: if + present."),
     M("application", "Choose: If I had a bicycle, I ...... to school on it.", "would ride", ["will ride", "rode", "would rode"], "Unreal condition: if + past, would + verb."),
     M("application", "Choose: If you ...... water to 100 degrees Celsius, it boils.", "heat", ["will heat", "heated", "would heat"], "Always true: if + present, present."),
     MA("approfondissement", "Match the beginning with the best ending.", [("If it rains,", "we will stay at home."), ("If I were rich,", "I would build a school."), ("If you heat ice,", "it melts."), ("If you hurry,", "you will catch the bus.")], "Check the verb forms on both sides."),
     O("Write two conditional sentences: one about something that may happen tomorrow, and one about something that is not true now.", "If it is sunny tomorrow, we will play football. If I were the headmaster, I would build a library.", "Full marks: first sentence if + present, will; second sentence if + past (were), would. Half marks for one correct sentence.", points=3),
     P("Put the verb in brackets in the correct form. (a) If you (practise), you will improve. (b) If Ngu (have) a phone, he would call you. (c) If we (mix) yellow and blue, we get green.",
       [PM("(a)", "practise", ["will practise", "practised", "would practise"], "Real: if + present simple."),
        PM("(b)", "had", ["has", "will have", "would have"], "Unreal: if + past simple."),
        PM("(c)", "mix", ["will mix", "mixed", "would mix"], "Fact: if + present simple.", points=2)])],
    [("If it ...... tomorrow, we will go to the beach.", "does not rain", ["will not rain", "would not rain", "did not rain"], "Real condition uses the present after if."),
     ("If I ...... you, I would ask the teacher.", "were", ["am", "will be", "would be"], "Advice: if I were you."),
     ("Which conditional sentence is correct?", "If he studies, he will pass.", ["If he will study, he will pass.", "If he studied, he will pass.", "If he would study, he will pass."], "No will after if."),
     ("'If you heat ice, it melts' is...", "always true", ["unreal", "in the past", "a command"], "It is a fact."),
     ("We will go if the weather ...... good.", "is", ["will be", "would be", "was"], "Present simple after if.")],
    ["Third conditional (if + past perfect, would have) is NOT covered; zero conditional is included although the syllabus may not name it."],
    prereq=["fslc-english-tenses-main"])

# =========================================================== chapter 7: reading skills
ch = p.chapter("reading-skills", "Reading skills: strategies for comprehension", REF)
PASSAGE1 = ("Market day in Bamenda is the busiest day of the week. Before the sun is up, Mama Joy loads her baskets of tomatoes, onions and green peppers onto a bus. "
            "Her daughter Neba helps her to carry them. At the market the sellers shout the prices, and buyers move slowly between the stalls. "
            "By noon, Mama Joy has sold almost everything. She is tired but happy. With the money, she buys school books for Neba and a bag of rice for the house.")
assert len(PASSAGE1) < 650, len(PASSAGE1)
fig_qw = grid([("Who?", "a person"), ("What?", "a thing, an event"), ("Where?", "a place"), ("When?", "a time"), ("Why?", "a reason"), ("How?", "the way")], 3, 115, 62)
build(ch, "comprehension-strategies", "Reading comprehension: strategies and question types", 35,
    ["Read a passage for the main idea and for details.", "Answer who, what, where, when, why and how questions in full sentences.", "Work out the meaning of a word from its context and make simple inferences."],
    [("key", "methode", "Three steps for comprehension", "1. **Read** the passage once quickly to get the main idea (**skimming**).\n2. **Read the questions**, then go back to the passage and look for the answer (**scanning**).\n3. **Answer** in your own words, in a full sentence, and check the spelling and punctuation. Do not copy long pieces of the passage."),
     ("fig", fig_qw, "The question words tell you what kind of answer to look for.", "Six boxes: Who asks for a person, What for a thing or event, Where for a place, When for a time, Why for a reason and How for the way."),
     ("text", "Read this passage.\n\n" + PASSAGE1),
     ("key", "retenir", "Kinds of questions", "- **Detail** question: the answer is written in the text (*Who helps Mama Joy?*).\n- **Main idea** question: what is the whole passage about? (*A busy market day.*)\n- **Inference**: the text does not say it directly, but you can work it out (*How does Mama Joy feel at the end? She is happy because she sold her goods.*).\n- **Vocabulary in context**: look at the words around the word you do not know."),
     ("key", "pieges", "Common mistakes", "- Answering from your own ideas instead of from the passage.\n- Copying a whole sentence that does not answer the question.\n- Writing a **phrase** when the question asks for a full sentence (follow the instruction).\n- Missing the question word: a *why* question needs a reason (**because**...)."),
     ("ex", "Example 1", "Using the passage on Bamenda market: Why does Mama Joy leave before the sun is up?", ["Look for the sentence about the early start: she loads her baskets and takes the bus before sunrise.", "The passage says market day is the busiest day of the week, so she needs to reach the market early to sell her goods.", "Answer: She leaves early because market day is very busy and she wants to sell her goods."], "She leaves early because market day is very busy and she wants to sell her goods."),
     ("ex", "Example 2", "What does 'stalls' mean in 'buyers move slowly between the stalls'?", ["Look at the words around it: buyers walk between them at the market and sellers stand there.", "A stall is a small table or place where goods are sold."], "A stall is a small place or table in the market where goods are sold.")],
    [M("application", "What is the best title for the passage about Bamenda market?", "A busy market day", ["A new school bag", "A bus journey", "Neba's birthday"], "The whole passage is about market day."),
     M("application", "Who helps Mama Joy to carry the baskets?", "Her daughter Neba", ["The bus driver", "A buyer", "Her husband"], "The passage says her daughter Neba helps her."),
     M("application", "What does Mama Joy buy with the money?", "School books and rice", ["Tomatoes and onions", "A new bus", "Green peppers"], "She buys school books for Neba and a bag of rice."),
     M("approfondissement", "How does Mama Joy feel at the end of the day?", "Tired but happy", ["Angry", "Afraid", "Bored"], "The passage says she is tired but happy (and the reason is that she sold almost everything)."),
     TF("approfondissement", "From the passage we know that Mama Joy sold nothing at the market.", False, "By noon she has sold almost everything."),
     P("Read: Ebai's goat was missing. He looked behind the kitchen and under the mango tree, but he did not find it. At last he heard a soft bleat from the old store. The goat had pushed the door open and was eating the maize. Ebai laughed, then he tied the door carefully so it would not happen again.",
       [PM("What is the main idea?", "Ebai finds his missing goat", ["Ebai grows maize", "A goat is sold", "A kitchen is built"], "The passage tells how Ebai looked for and found the goat."),
        PM("Where was the goat?", "In the old store", ["Behind the kitchen", "Under the mango tree", "In the market"], "He heard a bleat from the old store."),
        PM("What does 'bleat' mean?", "the sound a goat makes", ["a kind of food", "a type of door", "a small hut"], "It is a goat's cry, as the context shows."),
        PM("Why did Ebai tie the door?", "so the goat could not get in again", ["because he was angry", "because he sold the maize", "because the door was old and he liked it"], "He tied it so it would not happen again.", points=2)])],
    [("Skimming means...", "reading quickly for the main idea", ["reading every word slowly", "copying the text", "reading only the title"], "Skimming gives the general idea."),
     ("A 'why' question needs...", "a reason", ["a place", "a time", "a name"], "Use because in your answer."),
     ("To find the meaning of a new word we can...", "look at the words around it", ["skip the passage", "ask a friend only", "guess without reading"], "Context gives clues."),
     ("An inference is...", "an idea you work out from clues", ["a word in the title", "a spelling rule", "the last sentence"], "The text does not say it directly."),
     ("Your answer to a comprehension question should be...", "in your own words, in a full sentence", ["a copy of the whole passage", "only one letter", "your opinion without the text"], "Short, clear and based on the passage.")],
    ["The two passages are original texts written for this lesson. Passage readability for Class 6 should be checked by a teacher."],
    prereq=["fslc-english-reading-comprehension"])

