build(ch, "letter-writing", "Letter writing: formal and informal letters", 40,
    ["Write an informal letter to a friend or relative.", "Write a formal letter (request, apology, application) with the right layout.", "Use the right opening, closing and tone."],
    [("key", "definition", "Two kinds of letter", "An **informal (friendly) letter** is to a friend or a relative: it can be warm and chatty. A **formal letter** is to a person in authority (the headmaster, a company, an official): it is polite, short and to the point. Use **full forms** (do not, not don't) and no slang in a formal letter."),
     ("fig", fig_letter, "The layout of a formal letter.", "A page showing a formal letter: the sender's address and the date at the top right, the receiver's name and address at the left, Dear Sir, a subject line, the body, Yours faithfully and the sender's name."),
     ("key", "methode", "Layout of a formal letter", "1. Your address (top right), then the date.\n2. The name and address of the person you write to (left).\n3. **Dear Sir / Madam,** (or **Dear Mr Ndi,**).\n4. A **subject line** in capital letters.\n5. The body: why you write, the details, what you ask for, thanks.\n6. **Yours faithfully,** (if you wrote Dear Sir/Madam) or **Yours sincerely,** (if you wrote the person's name), then your name."),
     ("key", "retenir", "Informal letter", "Address and date at the top right, then **Dear Ada,** and a friendly first line (*I hope you are well.*). Write about the news, ask questions, then close with *Your friend,* or *Yours lovingly,* and your first name. There is no subject line and no receiver's address."),
     ("key", "pieges", "Common mistakes", "- Mixing the endings: *Dear Sir ... Yours sincerely* (should be faithfully).\n- Using slang, short forms or a long story in a formal letter.\n- Forgetting the date, the subject line or your name.\n- Writing the whole letter in one paragraph."),
     ("ex", "Example 1", "Which closing do you use after Dear Sir and after Dear Mr Ndi?", ["Dear Sir (the name is not known): Yours faithfully.", "Dear Mr Ndi (the name is known): Yours sincerely."], "Dear Sir ... Yours faithfully; Dear Mr Ndi ... Yours sincerely."),
     ("ex", "Example 2", "Write the first two sentences of a formal letter to your headmaster asking permission to be absent for one day.", ["Start with the reason and the request: I am writing to ask for your permission to be absent from school on Friday, 10 May.", "Give the reason politely: I have to attend my cousin's wedding in Bafoussam. I thank you in advance."], "I am writing to ask for your permission to be absent from school on Friday. I have to attend a family wedding in Bafoussam.")],
    [M("application", "A letter begins 'Dear Madam,'. It ends with...", "Yours faithfully,", ["Yours sincerely,", "Your friend,", "Bye bye,"], "Name not known: faithfully."),
     M("application", "Where does the date go in a letter?", "At the top right", ["At the bottom left", "After the signature", "In the middle"], "The sender's address and the date are at the top right."),
     M("application", "Which opening is suitable for a letter to a friend?", "Dear Neba, I hope you are well.", ["Dear Sir, I am writing to apply for the post of...", "To whom it may concern, I wish to complain.", "Madam, kindly be informed that..."], "Informal letters are friendly."),
     TF("approfondissement", "A formal letter should have a subject line.", True, "It tells the reader at once what the letter is about."),
     O("Write a short informal letter (about 5 to 6 sentences) to a friend in another town. Tell your friend about your school and ask two questions.", "12 Mile Road, Buea\n3 March 2025\nDear Neba,\nI hope you are well. I am writing to tell you about my new school. We have a big library and I like it very much. My favourite subject is science. What is your school like? Do you still play football?\nYour friend,\nBih", "Full marks: correct layout (address, date, Dear..., closing), friendly tone, at least two questions, correct spelling and punctuation, paragraphs.", points=4),
     O("Write a formal letter to the headmaster asking for permission to be absent from school for one day because of a family event. Use the correct layout and a polite tone.", "(Address and date)\nThe Headmaster\nGovernment Primary School\nDear Sir,\nREQUEST FOR PERMISSION TO BE ABSENT\nI am writing to ask for your permission to be absent from school on Friday, 10 May, because I have to attend a family wedding in Bafoussam. I will copy the lessons I miss. I thank you in advance.\nYours faithfully,\nEmma Fon", "Marks (out of 6): layout (2), clear request and reason (2), polite formal language (1), spelling and punctuation (1).", tier="examen", points=6)],
    [("A formal letter to someone whose name you do not know starts with...", "Dear Sir/Madam,", ["Hi,", "Dear friend,", "Hello there,"], "Dear Sir/Madam is the polite form."),
     ("Which ending goes with 'Dear Mr Ndi'?", "Yours sincerely,", ["Yours faithfully,", "See you,", "Love,"], "When the person's name is used we write sincerely."),
     ("What should the subject line of a formal letter do?", "tell what the letter is about", ["greet the reader", "give your address", "thank the teacher"], "It sums up the purpose."),
     ("Which sentence is too informal for a formal letter?", "I can't wait for ya to answer!", ["I thank you in advance.", "I am writing to request a copy.", "Please find my report attached."], "'Ya' and 'can't wait' are not formal."),
     ("A friendly letter closes with...", "Your friend, Ada", ["Yours faithfully", "Respectfully submitted", "Dear Sir"], "Informal closing.")],
    ["Formal letter layout (position of the date, subject line, 'Yours faithfully/sincerely') follows common Cameroonian anglophone practice; check against the FSLC marking scheme. Sample letters use fictional names."],
    prereq=["fslc-english-composition-main"])

fig_mtn = shapes([POLY([30, 200, 120, 120, 200, 45, 285, 120, 370, 200], fill="lightyellow", closed=False),
                  T(45, 222, "Beginning", 13, bold=True), T(115, 105, "Problem", 13, bold=True), T(200, 30, "Climax", 13, bold=True),
                  T(305, 105, "Solution", 13, bold=True), T(355, 222, "Ending", 13, bold=True)], 400, 240)
build(ch, "narrative-descriptive", "Writing a story and describing a person, place or event", 40,
    ["Plan a story with a beginning, a problem, a climax and an ending.", "Use the past tense, paragraphs and linking words in a story.", "Use the five senses and good adjectives in a description."],
    [("key", "methode", "Planning a story", "Before you write, make a short plan: **who** (characters), **where and when** (setting), **what happens** (the problem), **how it ends**. Use one paragraph for each part. Write in the **past tense** and use linking words: first, then, suddenly, after that, at last."),
     ("fig", fig_mtn, "The shape of a story.", "A line goes up like a mountain. The points are marked Beginning, Problem, Climax at the top, Solution and Ending."),
     ("key", "methode", "Writing a description", "To describe a place, a person or an event, use your **five senses**: what you see, hear, smell, taste and feel. Use exact adjectives (*a crowded, noisy market*) and comparisons (*as busy as ants*). Describe in order (from left to right, near to far) so that the reader can picture the scene."),
     ("key", "pieges", "Common mistakes", "- Starting to write without a plan, so that the story has no clear ending.\n- Changing from past to present tense in the middle of the story.\n- Using the same word again and again (*nice*, *good*): choose a more exact word.\n- Writing a long list of events with no paragraphs."),
     ("ex", "Example 1", "Plan a story called 'The Lost Bag'.", ["Beginning: Neba goes to the market with her mother and carries her new school bag.", "Problem and climax: she puts the bag down and it disappears; she searches and cries.", "Solution and ending: a kind seller found it; Neba thanks him and promises to be careful."], "A plan with a beginning, a problem, a climax and an ending."),
     ("ex", "Example 2", "Improve this sentence with a description: The dog was big.", ["Add adjectives that show what you see: huge, brown.", "Add an action and a sound: barked loudly at the gate.", "Together: The huge brown dog barked loudly at the gate."], "The huge brown dog barked loudly at the gate.")],
    [M("application", "A story should be written mainly in the...", "past tense", ["future tense", "present continuous tense", "imperative"], "Stories tell what happened, so we use the past tense."),
     M("application", "Which is the best linking word to show the end of a story?", "At last", ["First", "For example", "However"], "At last signals the ending."),
     M("application", "Which sentence uses the senses best?", "The sweet smell of ripe mangoes filled the noisy market.", ["The market was good.", "There were things in the market.", "I went to the market."], "It uses smell and sound with exact adjectives."),
     TF("approfondissement", "In a description we must only say what we see.", False, "We can also use hearing, smell, taste and touch."),
     O("Write a short descriptive paragraph (5 sentences) about your village, town or school. Use at least four adjectives and one comparison.", "My school stands on a green hill near the main road. The old brown buildings are surrounded by tall mango trees. In the morning the playground is as noisy as a market. The cool air smells of fresh grass. I am proud of my small, friendly school.", "Marks (out of 4): five sentences with good paragraph order (1), at least four adjectives (1), one comparison (1), correct spelling and punctuation (1).", points=4),
     O("Write a story of about 10 to 12 sentences with the title 'A Surprise on the Way to School'. Use the past tense and give your story a beginning, a problem and an ending.", "Last Monday I left home early to go to school. I walked along the dusty road and sang a song. Suddenly I heard a small cry from the bushes. I looked carefully and saw a tiny puppy with a hurt leg. I was afraid, but I picked it up gently. At the school gate my teacher saw me and called a nurse. She cleaned the leg and said it would be fine. At the end of the day my uncle came and took the puppy to the vet. I was happy that I had helped. I learned to be kind to animals.", "Marks (out of 6): plan with beginning, problem, ending (2); past tense (1); linking words and paragraphs (1); interesting detail (1); spelling and punctuation (1).", tier="examen", points=6)],
    [("The most exciting part of a story is the...", "climax", ["beginning", "title", "last word"], "The climax is the high point."),
     ("Which tense do we use for a story?", "past", ["future", "present perfect only", "none"], "Tell what happened."),
     ("The five senses are sight, hearing, smell, taste and...", "touch", ["speech", "memory", "balance"], "Touch completes the five senses."),
     ("'as busy as ants' is a...", "comparison (simile)", ["rhyme", "question", "title"], "It compares two things with 'as ... as'."),
     ("Before writing a story we should...", "make a plan", ["start at once", "copy a story", "write the ending first without thought"], "A plan keeps the story clear.")],
    ["Marking schemes for compositions are examples only; the FSLC scheme and expected length should be checked.", "Sample answers are original and should be proof-read."],
    prereq=["fslc-english-composition-main", "fslc-english-letter-writing"])

fig_poem = shapes([T(200, 30, "When rain drums on our roof at night,", 15), T(200, 62, "The street lamps glow with silver light.", 15),
                   T(200, 94, "The frogs sing out a happy song,", 15), T(200, 126, "And croak the whole night long.", 15),
                   T(375, 30, "A", 18, bold=True, color="blue"), T(375, 62, "A", 18, bold=True, color="blue"),
                   T(375, 94, "B", 18, bold=True, color="red"), T(375, 126, "B", 18, bold=True, color="red"),
                   T(200, 170, "night / light rhyme (A).  song / long rhyme (B).", 13)], 400, 195)
build(ch, "poetry-rhymes", "Poems and rhymes", 30,
    ["Find rhyming words and the rhyme scheme of a poem.", "Name the parts of a poem: line, stanza, rhythm.", "Recognise simile, alliteration and repetition."],
    [("key", "definition", "Parts of a poem", "A poem is written in **lines**. A group of lines is a **stanza** (verse). **Rhyme** is when words end with the same sound: night / light, song / long. **Rhythm** is the beat of the words when we read aloud. The **rhyme scheme** is the pattern of rhymes: we give the same letter to lines that rhyme (A A B B or A B A B)."),
     ("fig", fig_poem, "A four-line poem with the rhyme scheme A A B B.", "The four lines of a poem. The first two lines end with night and light and are marked A. The last two end with song and long and are marked B."),
     ("key", "definition", "Poetry words", "A **simile** compares two things with *like* or *as*: *as brave as a lion*. A **metaphor** says that one thing is another: *the moon is a silver coin*. **Alliteration** repeats the first sound: *Peter picked ripe red plums*. **Repetition** repeats a word or line for effect. To understand a poem: read it aloud, find the topic, find the feeling, and look at the pictures the words make in your mind."),
     ("key", "pieges", "Common mistakes", "- Thinking that rhyming words must be **spelled** alike: they must **sound** alike (light / write).\n- Answering a poem question with a long story: say what the poem is about and how it makes you feel, in your own words.\n- Mixing up simile (like/as) and metaphor (no like/as)."),
     ("ex", "Example 1", "Find the rhyming words in: The frogs sing out a happy song, and croak the whole night long.", ["Look at the last word of each line: song and long.", "They end with the same sound -ong, so they rhyme."], "song / long."),
     ("ex", "Example 2", "Complete the simile: as brave as a ......", ["A simile compares two things with as ... as.", "A lion is a common sign of courage, so: as brave as a lion."], "as brave as a lion.")],
    [M("application", "Which word rhymes with 'light'?", "night", ["lit", "list", "lice"], "light and night end with the same sound."),
     M("application", "Which sentence has alliteration?", "Peter picked ripe red plums.", ["The moon rose slowly.", "We went home at night.", "Ada has a green bag."], "Repeated first sounds: p, r."),
     M("application", "Which sentence contains a simile?", "He is as strong as an ox.", ["He is a lion in the fight.", "He lives in Buea.", "He ran fast."], "It uses as ... as."),
     MA("approfondissement", "Match the poetry word with its meaning.", [("stanza", "a group of lines"), ("rhyme", "words that end with the same sound"), ("simile", "a comparison with like or as"), ("rhythm", "the beat of the words")], "Basic poetry vocabulary."),
     TF("approfondissement", "'The moon is a silver coin' is a simile.", False, "It does not use like or as: it is a metaphor."),
     P("Read the poem: When rain drums on our roof at night, / The street lamps glow with silver light. / The frogs sing out a happy song, / And croak the whole night long.",
       [PM("Which words rhyme in lines 1 and 2?", "night and light", ["rain and roof", "lamps and glow", "silver and street"], "They end with the same sound."),
        PM("What is the rhyme scheme?", "A A B B", ["A B A B", "A B B A", "A B C D"], "Lines 1-2 rhyme and lines 3-4 rhyme."),
        PM("What is the poem about?", "a rainy night with singing frogs", ["a football match", "a market day", "a school lesson"], "It describes the sounds and sights at night in the rain."),
        PM("Which words show a sound?", "drums, sing, croak", ["glow, silver, light", "street, lamps, roof", "night, song, long"], "These words describe sounds.", points=2)])],
    [("A group of lines in a poem is a...", "stanza", ["chapter", "paragraph only", "rhyme"], "Stanza = verse."),
     ("Which pair rhymes?", "cake / lake", ["cat / cut", "pen / pan", "book / back"], "Cake and lake have the same ending sound."),
     ("'as quick as lightning' is a...", "simile", ["metaphor", "rhyme scheme", "stanza"], "As ... as."),
     ("Alliteration is...", "repeating the same first sound", ["a rhyme at the end", "a question", "a joke"], "Sally sells sea shells."),
     ("A rhyme scheme of A B A B means...", "lines 1 and 3 rhyme and lines 2 and 4 rhyme", ["all lines rhyme", "no line rhymes", "only the last line rhymes"], "Same letter, same rhyme.")],
    ["The poem is an original four-line poem written for this lesson. Metaphor is introduced only briefly; check the syllabus."],
    prereq=["fslc-english-vocabulary-families"])

fig_syl = shapes([RECT(35, 40, 60, 40, fill="lightblue"), RECT(105, 40, 60, 40, fill="lightblue"), RECT(175, 40, 60, 40, fill="lightblue"),
                  T(65, 66, "ba", 18, bold=True), T(135, 66, "na", 18, bold=True), T(205, 66, "na", 18, bold=True),
                  T(135, 105, "banana: 3 syllables, ba-NA-na", 12),
                  RECT(35, 135, 90, 40, fill="lightyellow"), RECT(135, 135, 90, 40, fill="lightyellow"),
                  T(80, 161, "man", 18, bold=True), T(180, 161, "go", 18, bold=True),
                  T(130, 195, "mango: 2 syllables, MAN-go", 12)], 400, 215)
L = build(ch, "oral-english-dictation", "Oral English and dictation: sounds, syllables, stress and listening", 30,
    ["Count the syllables in a word and find the stressed syllable.", "Pronounce and spell common difficult words, including silent letters.", "Use polite expressions and prepare a short oral talk; write a dictation correctly."],
    [("key", "definition", "Syllables and stress", "A **syllable** is a beat in a word that has one vowel sound: *pen* (1), *man-go* (2), *ba-na-na* (3), *beau-ti-ful* (3). In words of more than one syllable, one syllable is **stressed**: said louder and longer. *Teacher* is TEA-cher; *Cameroon* is Cam-er-OON; *banana* is ba-NA-na."),
     ("fig", fig_syl, "Syllables are the beats of a word.", "Boxes showing syllables. Banana has three boxes: ba, na and na. Mango has two boxes: man and go. Text says where the stress falls."),
     ("key", "retenir", "Silent letters and sounds", "Some letters are written but not said: **k** in *knife* and *know*; **w** in *write* and *answer*; **b** in *lamb* and *climb*; **h** in *hour* and *honest*; **gh** in *night* and *daughter*. Learn the commonly confused sounds in a list: ship / sheep, bit / beat, pull / pool."),
     ("key", "methode", "Dictation and speaking", "**Dictation**: listen to the whole sentence first, then write it while it is read in small pieces, then listen again and check spelling and punctuation. **Speaking**: greet politely (*Good morning, madam.*), ask politely (*May I come in, please?*), look at your listener, speak clearly and not too fast. For a short talk: introduction, two or three points, conclusion."),
     ("key", "pieges", "Common mistakes", "- Writing a word the way it sounds (*nife*, *rite*): check the silent letters.\n- Counting letters instead of **syllables**.\n- Forgetting capital letters and full stops in a dictation.\n- Speaking too fast, so that the listener cannot follow."),
     ("audio", "Listen and write. The children walked to school in the morning. They were happy, because the teacher had promised a story."),
     ("ex", "Example 1", "How many syllables are in 'beautiful'? Where is the stress?", ["Split into beats: beau-ti-ful: three syllables.", "The first syllable is said louder: BEAU-ti-ful."], "Three syllables; stress on the first: BEAU-ti-ful."),
     ("ex", "Example 2", "Which letters are silent in 'knife' and 'lamb'?", ["In knife the k is not pronounced: we say 'nife'.", "In lamb the b is silent: we say 'lam'."], "k in knife; b in lamb.")],
    [N("application", "How many syllables are in the word 'banana'?", 3, "ba-na-na: 3 syllables."),
     N("application", "How many syllables are in the word 'school'?", 1, "School is said in one beat."),
     M("application", "Which letter is silent in 'knife'?", "k", ["n", "f", "e"], "The k is not said."),
     M("approfondissement", "Which is the stressed syllable in 'Cameroon'?", "the last one (-oon)", ["the first one (Cam-)", "the second one (-er-)", "none"], "We say Cam-er-OON."),
     TF("approfondissement", "In a dictation we should listen to the whole sentence before we begin to write.", True, "Listening first helps us understand the meaning and write correctly."),
     P("Dictation check. The sentence read was: The children walked to school in the morning. Some pupils wrote it like this: The childrens walked to scool in the mourning.",
       [PM("Which word is spelled wrongly?", "scool", ["walked", "school", "children"], "The correct spelling is school (not scool)."),
        PM("Which is the correct spelling of the last word group?", "the morning", ["the mourning", "the morrning", "the mornig"], "Morning (the start of the day) is not mourning (sadness)."),
        PM("What is wrong with 'childrens'?", "children is already plural", ["it needs a capital letter", "it needs -er", "nothing is wrong"], "The plural of child is children; we do not add -s.", points=2),
        PN("How many syllables are in 'children'?", 2, "chil-dren.", points=1)])],
    [("How many syllables does 'mango' have?", "2", ["1", "3", "4"], "man-go."),
     ("Which letter is silent in 'write'?", "w", ["r", "i", "t"], "We say 'rite'."),
     ("In a dictation, the first thing to do is...", "listen to the whole sentence", ["write at once", "close your eyes", "talk to a friend"], "Listen first."),
     ("A polite way to ask permission to enter is...", "May I come in, please?", ["Open the door!", "I'm coming in.", "Let me in."], "Polite and clear."),
     ("The stressed syllable is the one that is...", "louder and longer", ["quieter", "silent", "spelled with a capital"], "Stress makes a syllable stand out.")],
    ["Syllable counts and stress patterns are for British English; the audio block is read by the device text-to-speech voice, so its pronunciation (accent) is not controlled. Dictation of the audio sentence should be checked by a teacher."],
    prereq=["fslc-english-spelling-rules"])

# =========================================================== second mock paper (20 marks)
LM = L
MOCK_PASSAGE = ("Every Saturday, Tabe goes with his grandfather to the family farm outside Bali. They leave early, when the grass is still wet. "
                "Tabe's job is to feed the chickens and to water the small vegetable garden. His grandfather digs the soil and plants cassava. "
                "At noon they sit under a big tree and eat boiled plantain. Tabe loves these days because he learns something new every time.")
assert len(MOCK_PASSAGE) < 600
a = add(LM, P("Read the passage and answer the questions. " + MOCK_PASSAGE,
              [PM("Where is the family farm?", "outside Bali", ["in Douala", "behind the school", "near the sea"], "The passage says the farm is outside Bali.", points=1),
               PM("What is Tabe's job on the farm?", "to feed the chickens and water the garden", ["to dig the soil", "to plant cassava", "to cook plantain"], "His grandfather digs and plants; Tabe feeds and waters.", points=1),
               PM("What does 'noon' mean?", "twelve o'clock in the day", ["early morning", "the evening", "midnight"], "At noon they eat: it is midday.", points=1),
               PM("Why does Tabe love these days?", "he learns something new every time", ["he does not go to school", "he eats cassava", "he plays football"], "The last sentence gives the reason.", points=1),
               PM("What is the best title for the passage?", "A Saturday on the farm", ["A new bicycle", "The market in Bali", "Cooking plantain"], "The whole passage is about Saturdays on the farm.", points=2)]), True)
bs = [add(LM, M("application", q, r, w, e), True) for q, r, w, e in [
    ("Choose the correct word: She sings ......", "beautifully", ["beautiful", "beauty", "more beautiful"], "An adverb describes the verb sings."),
    ("Choose the correct plural: The ...... are playing.", "babies", ["babys", "babyes", "babyies"], "Consonant + y becomes ies."),
    ("Change to the passive: Ada wrote the letter.", "The letter was written by Ada.", ["The letter written by Ada.", "The letter was wrote by Ada.", "Ada was written the letter."], "Past passive: was + written."),
    ("Change to indirect speech: He said, “I am tired.”", "He said that he was tired.", ["He said that I am tired.", "He said that he is tired?", "He said, that he was tired."], "am becomes was; I becomes he."),
    ("Choose: If it ...... tomorrow, we will stay at home.", "rains", ["will rain", "rained", "would rain"], "Present simple after if."),
    ("Which word is an antonym of 'happy'?", "unhappy", ["hungry", "honest", "heavy"], "Un + happy gives the opposite."),
    ("Which sentence is a command?", "Close the door.", ["She closed the door.", "Did you close the door?", "What a heavy door!"], "A command tells someone to do something."),
    ("Which word rhymes with 'night'?", "light", ["lit", "late", "nit"], "Same ending sound.")]]
c1 = add(LM, O("Write a letter of about 8 to 10 sentences to a friend or relative. Tell him or her about a day you enjoyed at school or at home, and invite him or her to visit you.", "12 Church Street, Bali\n5 May 2025\nDear Uncle,\nI hope you are well. Last Saturday we had a sports day at school. I ran in the 100 m race and came second. My friends cheered me and the teacher gave me a small medal. After the race we ate rice and stew. I was very tired but happy. Please come and visit us in the holidays. My mother says you can stay as long as you wish. Write soon.\nYour nephew,\nTabe", "Marks (out of 6): layout of an informal letter (2), content and invitation (2), grammar and tenses (1), spelling and punctuation (1).", points=6, tier="examen"), True)
p.mock("2", "FSLC mock paper 2 — English Language", 90,
       "Time: 1 hour 30 minutes. Marked out of 20. Answer ALL the questions. Read each question carefully and check your spelling. Practice paper written for CastBridge; the format (time, marks, sections) is to be checked against the official texts.",
       [("Section A — Reading comprehension (6 marks)", [a]), ("Section B — Grammar and vocabulary (8 marks)", bs), ("Section C — Composition: informal letter (6 marks)", [c1])])
p.write()
